import { NextRequest, NextResponse } from "next/server";
import { db } from "@/db";
import { affiliateCampaigns, campaignRedemptions, ownedBusinesses } from "@/db/schema";
import { and, eq, sql } from "drizzle-orm";
import { getAuthenticatedUser } from "@/lib/serverAuth";

/**
 * GET /api/business/campaigns/analytics
 * Returns transparent ROI and campaign attribution analytics:
 * - Redemptions count & total fiat revenue generated by campaign.
 * - Total Bunz invested from campaign budget.
 * - Net Effective Return: fiat revenue per Bunz spent.
 */
export async function GET(req: NextRequest) {
  try {
    const caller = await getAuthenticatedUser(req);
    if (!caller) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const campaignId = searchParams.get("campaignId");
    const businessId = searchParams.get("businessId");

    if (!campaignId || !businessId) {
      return NextResponse.json({ error: "Faltan campaignId y businessId" }, { status: 400 });
    }

    // Verify ownership
    const business = await db.query.ownedBusinesses.findFirst({
      where: and(eq(ownedBusinesses.id, businessId), eq(ownedBusinesses.ownerId, caller.id)),
    });

    if (!business) {
      return NextResponse.json({ error: "No autorizado para consultar analítica de este negocio" }, { status: 403 });
    }

    const [campaign] = await db.select().from(affiliateCampaigns)
      .where(and(
        eq(affiliateCampaigns.id, campaignId),
        eq(affiliateCampaigns.businessId, business.id)
      ))
      .limit(1);

    if (!campaign) {
      return NextResponse.json({ error: "Campaña no encontrada" }, { status: 404 });
    }

    // Query aggregated redemptions
    const [stats] = await db.select({
      totalRedemptions: sql<number>`count(*)`,
      totalFiatSpent: sql<number>`COALESCE(SUM(${campaignRedemptions.fiatSpent}), 0)`,
      totalBunzAwarded: sql<number>`COALESCE(SUM(${campaignRedemptions.bunzAwarded}), 0)`,
    }).from(campaignRedemptions)
      .where(eq(campaignRedemptions.campaignId, campaign.id));

    const totalRedemptions = Number(stats?.totalRedemptions ?? 0);
    const totalFiatSpent = Number(stats?.totalFiatSpent ?? 0);
    const totalBunzAwarded = Number(stats?.totalBunzAwarded ?? 0);

    // Attribution note: Fiat revenue generated specifically by transactions carrying this campaign coupon
    const averageTicket = totalRedemptions > 0 ? Math.round(totalFiatSpent / totalRedemptions) : 0;
    const fiatPerBunzRatio = totalBunzAwarded > 0 ? (totalFiatSpent / totalBunzAwarded).toFixed(2) : "0.00";

    return NextResponse.json({
      success: true,
      campaign: {
        id: campaign.id,
        title: campaign.title,
        status: campaign.status,
        campaignType: campaign.campaignType,
        targetSegment: campaign.targetSegment,
        rewardPercentage: campaign.rewardPercentage,
        budgetBunz: campaign.budgetBunz,
        budgetSpent: campaign.budgetSpent,
        startsAt: campaign.startsAt,
        expiresAt: campaign.expiresAt,
      },
      roi: {
        totalRedemptions,
        totalFiatSpent,
        totalBunzAwarded,
        averageTicket,
        fiatGeneratedPerBunzSpent: Number(fiatPerBunzRatio),
        attributionMethod: "TRANSACTION_COUPON_DIRECT_MATCH",
      },
    });
  } catch (error) {
    console.error("[CAMPAIGN_ANALYTICS_ERROR]", error);
    return NextResponse.json({ error: "Error al calcular analítica de campaña" }, { status: 500 });
  }
}
